G=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0],[0]*7,[0]*7,[0]*7]
occ={(r,c) for r in range(7) for c in range(7) if G[r][c]==8}
tiles=[]
for r in range(6):
 for c in range(6):
  sq={(r+dr,c+dc) for dr in range(2) for dc in range(2)}
  if sq<=occ: tiles.append(('sq',sq,1))
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   s={(r+dr,c+dc) for dr in range(2) for dc in range(2) if (dr,dc)!=miss}
   if s<=occ:
    color={(0,0):2,(1,0):3,(0,1):4}.get(miss,5)
    tiles.append((f'L{miss}',s,color))
bycell={x:[] for x in occ}
for t in tiles:
 for x in t[1]: bycell[x].append(t)
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem,key=lambda x:sum(t[1]<=rem for t in bycell[x]))
 for t in bycell[x]:
  if t[1]<=rem: rec(rem-t[1],chosen+[t])
rec(occ,[])
len(sol), [[(t[0],sorted(t[1])) for t in s] for s in sol[:5]]

src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Tile the figure with 2x2 squares and L triominoes. The colors mark
    # the tile types and the missing corner of each L.
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2))
            if square <= occupied:
                tiles.append((square, 1))
            for missing, color in (((0, 0), 2), ((1, 0), 3), ((0, 1), 4), ((1, 1), 1)):
                cells = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2)
                                  if (dr, dc) != missing)
                if cells <= occupied:
                    tiles.append((cells, color))
    by_cell = {cell: [] for cell in occupied}
    for cells, color in tiles:
        for cell in cells:
            by_cell[cell].append((cells, color))

    def search(remaining, chosen):
        if not remaining:
            return chosen
        cell = min(remaining, key=lambda p: sum(cells <= remaining for cells, _ in by_cell[p]))
        for cells, color in by_cell[cell]:
            if cells <= remaining:
                result = search(remaining - cells, chosen + [(cells, color)])
                if result is not None:
                    return result
        return None

    tiling = search(occupied, [])
    out = [[0 for _ in range(w)] for _ in range(h)]
    if tiling is not None:
        for cells, color in tiling:
            for r, c in cells:
                out[r][c] = color
    return out
'''
